{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The stated inequalities define a feasible triangle, and its optimal boundary can be shown exactly."
  },
  "source": {
    "question": "Show me multiple optimal solutions graphically when Z = 2x + 2y is maximized over x >= 0, y >= 0 and x + y <= 5."
  },
  "quantities": [
    {
      "id": "cx",
      "symbol": "coefficient of x",
      "value": 2,
      "provenance": "given",
      "sourceText": "Z = 2x + 2y"
    },
    {
      "id": "cy",
      "symbol": "coefficient of y",
      "value": 2,
      "provenance": "given",
      "sourceText": "Z = 2x + 2y"
    },
    {
      "id": "b",
      "symbol": "constraint bound",
      "value": 5,
      "provenance": "given",
      "sourceText": "x + y <= 5"
    },
    {
      "id": "zmax",
      "symbol": "maximum Z",
      "value": 10,
      "provenance": "derived",
      "dependsOn": ["cx", "cy", "b"],
      "sourceText": "On x + y = 5, Z = 2(x + y) = 2(5) = 10."
    }
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "coordinate axes"},
    {"id": "feasible", "kind": "linear_region", "role": "feasible triangle"},
    {"id": "origin", "kind": "point", "role": "feasible vertex", "label": "(0,0)"},
    {"id": "xIntercept", "kind": "point", "role": "optimal endpoint", "label": "(5,0)"},
    {"id": "yIntercept", "kind": "point", "role": "optimal endpoint", "label": "(0,5)"},
    {"id": "optimalEdge", "kind": "segment", "role": "entire optimal boundary"},
    {"id": "example", "kind": "point", "role": "interior optimal example", "label": "(2.5,2.5)"}
  ],
  "constructions": [
    {
      "id": "makeAxes",
      "operator": "axes",
      "inputs": {"xMin": -0.5, "xMax": 5.8, "yMin": -0.5, "yMax": 5.8},
      "outputs": ["axes"]
    },
    {
      "id": "makeFeasible",
      "operator": "linear_feasible_region",
      "inputs": {
        "variables": ["x", "y"],
        "constraints": ["x >= 0", "y >= 0", "x + y <= 5"],
        "objective": {"expression": "2x + 2y", "sense": "max"}
      },
      "outputs": ["feasible"]
    },
    {
      "id": "makeOrigin",
      "operator": "point",
      "inputs": {"x": 0, "y": 0, "coordinateSpace": "world"},
      "outputs": ["origin"]
    },
    {
      "id": "makeXIntercept",
      "operator": "point",
      "inputs": {"x": 5, "y": 0, "coordinateSpace": "world"},
      "outputs": ["xIntercept"]
    },
    {
      "id": "makeYIntercept",
      "operator": "point",
      "inputs": {"x": 0, "y": 5, "coordinateSpace": "world"},
      "outputs": ["yIntercept"]
    },
    {
      "id": "makeOptimalEdge",
      "operator": "segment",
      "inputs": {"start": "xIntercept", "end": "yIntercept"},
      "outputs": ["optimalEdge"]
    },
    {
      "id": "makeExample",
      "operator": "point",
      "inputs": {"x": 2.5, "y": 2.5, "coordinateSpace": "world"},
      "outputs": ["example"]
    }
  ],
  "relations": [],
  "assertions": [
    {
      "id": "exampleOnOptimalEdge",
      "predicate": "on",
      "entities": ["example", "optimalEdge"],
      "expected": true,
      "severity": "fatal"
    },
    {
      "id": "exampleBetweenEndpoints",
      "predicate": "between",
      "entities": ["example", "xIntercept", "yIntercept"],
      "expected": true,
      "severity": "fatal"
    }
  ],
  "annotations": [
    {
      "id": "constraintLabel",
      "kind": "label",
      "targetIds": ["optimalEdge"],
      "text": "x + y = 5"
    },
    {
      "id": "objectiveLabel",
      "kind": "callout",
      "targetIds": ["feasible"],
      "text": "Maximize Z = 2x + 2y"
    },
    {
      "id": "edgeHighlight",
      "kind": "highlight",
      "targetIds": ["optimalEdge"]
    },
    {
      "id": "maximumLabel",
      "kind": "label",
      "targetIds": ["optimalEdge"],
      "text": "Z = 10",
      "quantityId": "zmax"
    }
  ],
  "requiredEntityIds": [
    "axes",
    "feasible",
    "origin",
    "xIntercept",
    "yIntercept",
    "optimalEdge",
    "example"
  ],
  "revealGroups": [
    {
      "id": "setup",
      "entityIds": ["axes", "feasible", "origin", "xIntercept", "yIntercept"],
      "dependsOn": [],
      "narrationCue": "Plot the feasible triangle and the objective."
    },
    {
      "id": "optimum",
      "entityIds": ["optimalEdge", "example"],
      "dependsOn": ["setup"],
      "narrationCue": "Every point on the highlighted edge satisfies x + y = 5, so every point on it gives the same maximum Z = 10."
    }
  ],
  "teachingTimeline": [
    {
      "id": "showSetup",
      "revealGroupId": "setup",
      "annotationIds": ["constraintLabel", "objectiveLabel"]
    },
    {
      "id": "showOptimum",
      "revealGroupId": "optimum",
      "annotationIds": ["edgeHighlight", "maximumLabel"]
    }
  ]
}

